const t={preflight:{intro:{t:0,b:{t:2,i:[{t:3}],s:"プリント開始の準備が整っているかを、読み取り専用で素早く確認します。"}},refresh:{t:0,b:{t:2,i:[{t:3}],s:"再チェック"}},checking:{t:0,b:{t:2,i:[{t:3}],s:"確認中…"}},ready:{t:0,b:{t:2,i:[{t:3}],s:"プリントの準備完了"}},notReady:{t:0,b:{t:2,i:[{t:3}],s:"プリントの準備ができていません"}},checks:{unreachable:{fail:{t:0,b:{t:2,i:[{t:3}],s:"プリンターに接続できません"}}},klippy:{pass:{t:0,b:{t:2,i:[{t:3}],s:"Klipper の準備ができています"}},fail:{t:0,b:{t:2,i:[{t:3,v:"Klipper の準備ができていません（状態: "},{t:4,k:"state"},{t:3,v:"）"}]}}},idle:{pass:{t:0,b:{t:2,i:[{t:3}],s:"進行中のプリントはありません"}},fail:{t:0,b:{t:2,i:[{t:3,v:"すでにプリントが実行中です（"},{t:4,k:"state"},{t:3,v:"）"}]}}},homed:{pass:{t:0,b:{t:2,i:[{t:3}],s:"すべての軸がホーミング済みです"}},fail:{t:0,b:{t:2,i:[{t:3,v:"ホーミングされていない軸があります（"},{t:4,k:"axes"},{t:3,v:"）。プリント開始時には通常まずホーミングが行われます"}]}}}},help:{guide:{t:0,b:{t:2,i:[{t:3}],s:"ガイド"}},guideTitle:{t:0,b:{t:2,i:[{t:3}],s:"プリント前チェックガイド"}},close:{t:0,b:{t:2,i:[{t:3}],s:"閉じる"}},topics:{overview:{title:{t:0,b:{t:2,i:[{t:3}],s:"プリント前チェックとは？"}},body:{t:0,b:{t:2,i:[{t:3}],s:"プリンターが開始準備できているかを読み取り専用で確認します。動かしたり何かを変更したりすることは一切なく、状態を報告するだけです。重大な障害があると判定が赤くなり、警告は知らせるだけでブロックはしません。"}}},checks:{title:{t:0,b:{t:2,i:[{t:3}],s:"チェックする内容"}},body:{t:0,b:{t:2,i:[{t:3}],s:"Klipper の準備ができているか（シャットダウンやエラー状態でないか）、すでにプリントが実行中でないか、そして軸がホーミング済みかどうか（プリント開始時に通常まずホーミングされるため、これは参考情報です）を確認します。"}}},glossary:{title:{t:0,b:{t:2,i:[{t:3}],s:"用語集"}}}},glossary:{klippyState:{term:{t:0,b:{t:2,i:[{t:3}],s:"Klipper の状態"}},def:{t:0,b:{t:2,i:[{t:3}],s:"Klipper 自身のステータスです。'ready'（準備完了）は接続済みで待機中であることを意味し、'shutdown'（シャットダウン）や 'error'（エラー）は解除するまでプリントできないことを意味します。"}}},homing:{term:{t:0,b:{t:2,i:[{t:3}],s:"ホーミング"}},def:{t:0,b:{t:2,i:[{t:3}],s:"各軸をエンドストップまで動かし、プリンターがツールヘッドの位置を把握できるようにすることです。ほとんどのプリント開始ルーチンは自動でホーミングを行います。"}}}}}}};export{t as default};
